<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Registration\Application\Usecase\UpdateClientRegistration;

use Civi\Lughauth\Features\Oidc\Registration\Domain\ClientRegistrationData;
use Civi\Lughauth\Features\Oidc\Registration\Domain\ClientRegistrationRequest;
use Civi\Lughauth\Features\Oidc\Registration\Domain\Gateway\ClientRegistrationGateway;
use Civi\Lughauth\Features\Oidc\Registration\Domain\Exception\RegistrationException;

final class UpdateClientRegistrationUsecase
{
    private const array FORBIDDEN_URI_SCHEMES = ['javascript', 'data', 'vbscript'];

    public function __construct(
        private readonly ClientRegistrationGateway $gateway,
    ) {
    }

    public function update(string $clientId, string $registrationAccessToken, ClientRegistrationRequest $request): ClientRegistrationData
    {
        foreach ($request->redirectUris as $uri) {
            $scheme = strtolower((string) parse_url($uri, PHP_URL_SCHEME));
            if (in_array($scheme, self::FORBIDDEN_URI_SCHEMES, true) || $scheme === '') {
                throw RegistrationException::invalidRedirectUri($uri);
            }
        }

        $data = $this->gateway->update($clientId, $registrationAccessToken, $request);
        if ($data === null) {
            throw RegistrationException::invalidToken();
        }
        return $data;
    }
}
